DO $stage$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "lasana-dumplings-al-vapor", "public_path": "/lasana-dumplings-al-vapor", "title": "Lasaña de dumplings al vapor con cerdo y wonton", "excerpt": "Lasaña de dumplings con capas de wonton, cerdo y repollo, sin plegar piezas. Fotos paso a paso, cocción al vapor y consejos para un relleno jugoso.", "summary": "Esta lasaña cambia la pasta italiana por obleas finas de wonton y se cocina al vapor. Entre las capas lleva cerdo, repollo, jengibre y cebolleta: el sabor de un dumpling sin formar cada pieza. Rinde 4 porciones y necesita unos 70 minutos, incluido un reposo de 5 minutos.", "content_html": "<h2>Sobre esta receta</h2><p>Esta lasaña cambia la pasta italiana por obleas finas de wonton y se cocina al vapor. Entre las capas lleva cerdo, repollo, jengibre y cebolleta: el sabor de un dumpling sin formar cada pieza. Rinde 4 porciones y necesita unos 70 minutos, incluido un reposo de 5 minutos.</p>", "notes": "<h3>Consejos y conservación</h3><p>Usa obleas finas de wonton; las láminas secas de lasaña italiana requieren otra hidratación y no son un cambio directo. Al aumentar raciones, reparte en más fuentes manteniendo capas finas; no dupliques el tiempo automáticamente y comprueba siempre el centro. Si sustituyes por pollo molido, el centro debe alcanzar 74 °C. Refrigera las sobras pronto a 4 °C o menos, consume en 3 días y recalienta hasta 74 °C. Contiene trigo, soja y sésamo; algunas obleas llevan huevo. El tiempo de cocción incluye aproximadamente 5 minutos para calentar el agua y 35 de vapor.</p><h3>Fuentes</h3><ul><li><a href=\"https://lindseyeatsla.com/dumpling-lasagna/\">Lindsey Eats — dumpling lasagna technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling and temperatures</a></li></ul>", "ingredients": [{"name": "carne de cerdo molida", "amount": "400", "unit": "g"}, {"name": "repollo blanco, limpio y seco", "amount": "150", "unit": "g"}, {"name": "cebolleta", "amount": "40", "unit": "g"}, {"name": "ajo pelado", "amount": "8", "unit": "g"}, {"name": "jengibre fresco pelado", "amount": "10", "unit": "g"}, {"name": "salsa de soja", "amount": "30", "unit": "g"}, {"name": "aceite de sésamo tostado", "amount": "10", "unit": "g"}, {"name": "obleas de wonton finas", "amount": "150", "unit": "g"}, {"name": "agua para humedecer las capas; aparte, agua para la vaporera", "amount": "90", "unit": "ml"}, {"name": "semillas de sésamo", "amount": "5", "unit": "g"}], "steps": [{"title": "Pica las verduras", "content": "Lava y seca repollo y cebolleta. Pícalos muy finos; reserva un poco de cebolleta para servir. Ralla el ajo y el jengibre.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-01.webp", "image_alt": "Pica las verduras — Lasaña de dumplings al vapor con cerdo y wonton"}, {"title": "Mezcla el relleno", "content": "En un bol mezcla el cerdo frío con el repollo, la cebolleta restante, ajo, jengibre, soja y aceite de sésamo. Remueve hasta integrar, sin probarlo crudo.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-02.webp", "image_alt": "Mezcla el relleno — Lasaña de dumplings al vapor con cerdo y wonton"}, {"title": "Prepara la vaporera", "content": "Comprueba que una fuente cuadrada apta para vapor de 20 cm cabe en una olla amplia con tapa. Colócala sobre una rejilla estable; el agua debe quedar debajo, sin tocarla. Retira la fuente y calienta el agua.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-03.webp", "image_alt": "Prepara la vaporera — Lasaña de dumplings al vapor con cerdo y wonton"}, {"title": "Monta la primera capa", "content": "Cubre la base de la fuente con obleas de wonton ligeramente humedecidas, solapándolas lo mínimo. Extiende encima la mitad del relleno en una capa fina y pareja.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-04.webp", "image_alt": "Monta la primera capa — Lasaña de dumplings al vapor con cerdo y wonton"}, {"title": "Completa las capas", "content": "Añade otra capa de obleas, el resto del relleno y una última capa de obleas: son tres de masa y dos de carne. Reparte el agua medida entre la superficie y los bordes.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-05.webp", "image_alt": "Completa las capas — Lasaña de dumplings al vapor con cerdo y wonton"}, {"title": "Cocina al vapor", "content": "Pon la fuente en la rejilla con cuidado y tapa la olla. Cocina con vapor constante unos 35 minutos desde que vuelva a hervir; repón agua caliente si hace falta, sin mojarte con el vapor.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-06.webp", "image_alt": "Cocina al vapor — Lasaña de dumplings al vapor con cerdo y wonton"}, {"title": "Comprueba el centro", "content": "Mide el relleno en el centro: debe alcanzar al menos 71 °C. Si no llega, sigue cocinando y comprueba de nuevo. Retira con guantes y deja reposar 5 minutos.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-07.webp", "image_alt": "Comprueba el centro — Lasaña de dumplings al vapor con cerdo y wonton"}, {"title": "Sirve las capas jugosas", "content": "Reparte la cebolleta reservada y el sésamo. Corta en porciones y sirve con sus jugos; no necesita una costra dorada porque es una preparación al vapor.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-08.webp", "image_alt": "Sirve las capas jugosas — Lasaña de dumplings al vapor con cerdo y wonton"}], "category": "Platos principales", "course": "Platos principales", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 25, "cook_time_minutes": 40, "total_time_minutes": 70, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "alt": "Lasaña de wonton al vapor con capas de cerdo y repollo, cebolleta y sésamo"}], "video_urls": [], "keywords": ["lasaña de dumplings", "dumpling lasagna", "lasaña de wonton", "dumplings sin plegar"], "nutrition": {"calories": 422.9, "protein_g": 22.2, "carbs_g": 26.8, "fat_g": 25.0, "estimated": true, "serving_size": "1 de 4 porciones", "note": "Estimación por ración; los productos y el rendimiento pueden cambiar los valores.", "source": "Cálculo editorial con perfiles genéricos de ingredientes", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Lasaña de dumplings al vapor con cerdo y wonton", "description": "Lasaña de dumplings con capas de wonton, cerdo y repollo, sin plegar piezas. Fotos paso a paso, cocción al vapor y consejos para un relleno jugoso.", "author": "Néstor Bastidas", "image_alt": "Lasaña de wonton al vapor con capas de cerdo y repollo, cebolleta y sésamo", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-16x9.webp"], "faq": [{"q": "¿Se hace en el horno?", "a": "Esta versión se cocina al vapor en una fuente sobre rejilla, dentro de una olla tapada. No usa queso ni salsa de tomate."}, {"q": "¿Cómo evito capas secas?", "a": "Humedece las obleas, solápalas poco y reparte el agua medida sobre la masa y por los bordes. Mantén el vapor constante."}, {"q": "¿El color indica que el cerdo está listo?", "a": "No es una comprobación fiable. Usa un termómetro y exige al menos 71 °C en el relleno del centro."}], "additional_time_minutes": 5}, "published": false, "editorial_status": "draft"}, {"language": "en", "slug": "steamed-dumpling-lasagna", "public_path": "/en/steamed-dumpling-lasagna", "title": "Steamed Dumpling Lasagna with Pork and Wonton Wrappers", "excerpt": "Layer wonton wrappers with pork and cabbage for steamed dumpling lasagna. No folding, with step photos and tips for tender, juicy layers.", "summary": "Thin wonton wrappers replace Italian pasta in this steamed lasagna. Pork, cabbage, ginger and scallions fill the layers, bringing dumpling flavors without shaping individual pieces. Makes 4 servings in about 70 minutes, including a 5-minute rest.", "content_html": "<h2>About this recipe</h2><p>Thin wonton wrappers replace Italian pasta in this steamed lasagna. Pork, cabbage, ginger and scallions fill the layers, bringing dumpling flavors without shaping individual pieces. Makes 4 servings in about 70 minutes, including a 5-minute rest.</p>", "notes": "<h3>Tips and storage</h3><p>Use thin wonton wrappers; dry Italian lasagna sheets need different hydration and are not a direct substitute. For larger batches, use more dishes and keep layers thin; do not automatically double cooking time, and always check the center. Ground chicken must reach 74 °C / 165 °F. Refrigerate leftovers promptly at 4 °C / 40 °F or below, eat within 3 days and reheat to 74 °C / 165 °F. Contains wheat, soy and sesame; some wrappers contain egg. Cooking time allows roughly 5 minutes to heat the water and 35 minutes of steaming.</p><h3>Sources</h3><ul><li><a href=\"https://lindseyeatsla.com/dumpling-lasagna/\">Lindsey Eats — dumpling lasagna technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling and temperatures</a></li></ul>", "ingredients": [{"name": "ground pork", "amount": "400", "unit": "g"}, {"name": "white cabbage, trimmed and dried", "amount": "150", "unit": "g"}, {"name": "scallions", "amount": "40", "unit": "g"}, {"name": "peeled garlic", "amount": "8", "unit": "g"}, {"name": "peeled fresh ginger", "amount": "10", "unit": "g"}, {"name": "soy sauce", "amount": "30", "unit": "g"}, {"name": "toasted sesame oil", "amount": "10", "unit": "g"}, {"name": "thin wonton wrappers", "amount": "150", "unit": "g"}, {"name": "water to moisten the layers; extra water for the steamer", "amount": "90", "unit": "ml"}, {"name": "sesame seeds", "amount": "5", "unit": "g"}], "steps": [{"title": "Chop the vegetables", "content": "Wash and dry the cabbage and scallions. Chop very finely, reserving a little scallion for serving. Grate the garlic and ginger.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-01.webp", "image_alt": "Chop the vegetables — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}, {"title": "Mix the filling", "content": "Combine cold ground pork with cabbage, remaining scallions, garlic, ginger, soy sauce and sesame oil. Stir until evenly combined; do not taste raw filling.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-02.webp", "image_alt": "Mix the filling — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}, {"title": "Set up the steamer", "content": "Check that a 20 cm / 8-inch square steam-safe dish fits inside a wide lidded pot on a stable rack. Keep water below the dish. Remove the dish and heat the water.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-03.webp", "image_alt": "Set up the steamer — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}, {"title": "Build the first layer", "content": "Cover the dish base with lightly moistened wonton wrappers, overlapping as little as possible. Spread half the filling over them in a thin, even layer.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-04.webp", "image_alt": "Build the first layer — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}, {"title": "Finish the layers", "content": "Add another wrapper layer, the remaining filling and a final wrapper layer: three pasta layers and two meat layers. Distribute the measured water over the top and edges.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-05.webp", "image_alt": "Finish the layers — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}, {"title": "Steam the lasagna", "content": "Carefully set the dish on the rack and cover the pot. Steam steadily for about 35 minutes once boiling resumes; top up with hot water if needed, avoiding steam burns.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-06.webp", "image_alt": "Steam the lasagna — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}, {"title": "Check the center", "content": "Probe the center filling: it must reach at least 71 °C / 160 °F. Continue cooking and recheck if needed. Remove with oven gloves and rest for 5 minutes.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-07.webp", "image_alt": "Check the center — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}, {"title": "Serve the juicy layers", "content": "Scatter the reserved scallions and sesame seeds over the top. Cut into portions and serve with the juices; this steamed dish does not need a browned crust.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-08.webp", "image_alt": "Serve the juicy layers — Steamed Dumpling Lasagna with Pork and Wonton Wrappers"}], "category": "Main dishes", "course": "Main dishes", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 25, "cook_time_minutes": 40, "total_time_minutes": 70, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "alt": "Steamed wonton lasagna with layers of pork and cabbage, scallions and sesame"}], "video_urls": [], "keywords": ["dumpling lasagna", "steamed dumpling lasagna", "wonton lasagna", "no fold dumplings"], "nutrition": {"calories": 422.9, "protein_g": 22.2, "carbs_g": 26.8, "fat_g": 25.0, "estimated": true, "serving_size": "1 of 4 servings", "note": "Estimated per serving; products and yield can change these values.", "source": "Editorial calculation using generic ingredient profiles", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Steamed Dumpling Lasagna with Pork and Wonton Wrappers", "description": "Layer wonton wrappers with pork and cabbage for steamed dumpling lasagna. No folding, with step photos and tips for tender, juicy layers.", "author": "Néstor Bastidas", "image_alt": "Steamed wonton lasagna with layers of pork and cabbage, scallions and sesame", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-16x9.webp"], "faq": [{"q": "Is it baked?", "a": "This version steams in a dish on a rack inside a covered pot. It has no cheese or tomato sauce."}, {"q": "How do I prevent dry wrappers?", "a": "Moisten the wrappers, avoid heavy overlaps and spread the measured water over the surface and edges. Keep the steam steady."}, {"q": "Does pork color prove it is cooked?", "a": "Color is unreliable. Use a thermometer and check for at least 71 °C / 160 °F in the center filling."}], "additional_time_minutes": 5}, "published": false, "editorial_status": "draft"}, {"language": "de", "slug": "dumpling-lasagne-gedaempft", "public_path": "/de/dumpling-lasagne-gedaempft", "title": "Gedämpfte Dumpling-Lasagne mit Schweinefleisch", "excerpt": "Dumpling-Lasagne aus Wan-Tan-Blättern, Schweinehack und Weißkohl, ganz ohne Falten. Mit Schrittbildern und Tipps für saftige Schichten.", "summary": "Dünne Wan-Tan-Blätter ersetzen hier italienische Pasta; gegart wird im Dampf. Schweinehack, Kohl, Ingwer und Frühlingszwiebeln bringen Dumpling-Aromen ohne einzelne Teigtaschen. Für 4 Portionen, etwa 70 Minuten einschließlich 5 Minuten Ruhezeit.", "content_html": "<h2>Über dieses Rezept</h2><p>Dünne Wan-Tan-Blätter ersetzen hier italienische Pasta; gegart wird im Dampf. Schweinehack, Kohl, Ingwer und Frühlingszwiebeln bringen Dumpling-Aromen ohne einzelne Teigtaschen. Für 4 Portionen, etwa 70 Minuten einschließlich 5 Minuten Ruhezeit.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>Dünne Wan-Tan-Blätter verwenden. Getrocknete italienische Lasagneplatten benötigen eine andere Wassermenge und sind kein direkter Ersatz. Größere Mengen auf mehrere Formen verteilen und dünne Schichten beibehalten; die Garzeit nicht automatisch verdoppeln, sondern den Kern messen. Hähnchenhack muss 74 °C erreichen. Reste zügig bei höchstens 4 °C kühlen, innerhalb von 3 Tagen essen und auf 74 °C erhitzen. Enthält Weizen, Soja und Sesam; manche Teigblätter enthalten Ei. Die Garzeit umfasst etwa 5 Minuten Aufheizen und 35 Minuten Dämpfen.</p><h3>Quellen</h3><ul><li><a href=\"https://lindseyeatsla.com/dumpling-lasagna/\">Lindsey Eats — dumpling lasagna technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling and temperatures</a></li></ul>", "ingredients": [{"name": "Schweinehackfleisch", "amount": "400", "unit": "g"}, {"name": "Weißkohl, geputzt und trocken", "amount": "150", "unit": "g"}, {"name": "Frühlingszwiebeln", "amount": "40", "unit": "g"}, {"name": "geschälter Knoblauch", "amount": "8", "unit": "g"}, {"name": "geschälter frischer Ingwer", "amount": "10", "unit": "g"}, {"name": "Sojasauce", "amount": "30", "unit": "g"}, {"name": "geröstetes Sesamöl", "amount": "10", "unit": "g"}, {"name": "dünne Wan-Tan-Teigblätter", "amount": "150", "unit": "g"}, {"name": "Wasser zum Befeuchten; zusätzlich Wasser zum Dämpfen", "amount": "90", "unit": "ml"}, {"name": "Sesamsamen", "amount": "5", "unit": "g"}], "steps": [{"title": "Gemüse zerkleinern", "content": "Kohl und Frühlingszwiebeln waschen und trocknen. Sehr fein schneiden, etwas Frühlingszwiebel zum Servieren zurücklegen. Knoblauch und Ingwer reiben.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-01.webp", "image_alt": "Gemüse zerkleinern — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}, {"title": "Füllung mischen", "content": "Kaltes Schweinehack mit Kohl, übrigen Frühlingszwiebeln, Knoblauch, Ingwer, Sojasauce und Sesamöl gleichmäßig mischen. Die rohe Füllung nicht probieren.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-02.webp", "image_alt": "Füllung mischen — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}, {"title": "Dämpfer vorbereiten", "content": "Prüfen, ob eine quadratische, dampfgeeignete 20-cm-Form auf einem stabilen Gitter in einen breiten Topf mit Deckel passt. Wasser darf die Form nicht berühren. Form herausnehmen und Wasser erhitzen.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-03.webp", "image_alt": "Dämpfer vorbereiten — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}, {"title": "Erste Schicht einlegen", "content": "Den Formboden mit leicht befeuchteten Wan-Tan-Blättern möglichst ohne starke Überlappungen bedecken. Die Hälfte der Füllung dünn und gleichmäßig darauf verteilen.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-04.webp", "image_alt": "Erste Schicht einlegen — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}, {"title": "Schichten fertigstellen", "content": "Eine weitere Teigschicht, die restliche Füllung und eine letzte Teigschicht einlegen: drei Teig- und zwei Fleischschichten. Abgemessenes Wasser auf Oberfläche und Ränder verteilen.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-05.webp", "image_alt": "Schichten fertigstellen — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}, {"title": "Lasagne dämpfen", "content": "Form vorsichtig aufs Gitter stellen und den Topf schließen. Ab erneutem Kochen etwa 35 Minuten gleichmäßig dämpfen. Bei Bedarf heißes Wasser nachfüllen; vor Dampf schützen.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-06.webp", "image_alt": "Lasagne dämpfen — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}, {"title": "Kerntemperatur prüfen", "content": "In der mittleren Füllung mindestens 71 °C messen. Falls nötig weitergaren und erneut prüfen. Mit Topfhandschuhen herausheben und 5 Minuten ruhen lassen.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-07.webp", "image_alt": "Kerntemperatur prüfen — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}, {"title": "Saftige Schichten servieren", "content": "Zurückgelegte Frühlingszwiebeln und Sesam darüberstreuen. In Portionen schneiden und mit dem Garsaft servieren; eine braune Kruste ist bei diesem Dampfgericht nicht nötig.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-08.webp", "image_alt": "Saftige Schichten servieren — Gedämpfte Dumpling-Lasagne mit Schweinefleisch"}], "category": "Hauptgerichte", "course": "Hauptgerichte", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 25, "cook_time_minutes": 40, "total_time_minutes": 70, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "alt": "Gedämpfte Wan-Tan-Lasagne mit Schweinehack, Kohl, Frühlingszwiebeln und Sesam"}], "video_urls": [], "keywords": ["Dumpling Lasagne", "Wan Tan Lasagne", "gedämpfte Lasagne", "Dumplings ohne Falten"], "nutrition": {"calories": 422.9, "protein_g": 22.2, "carbs_g": 26.8, "fat_g": 25.0, "estimated": true, "serving_size": "1 von 4 Portionen", "note": "Schätzwerte pro Portion; Produkte und Ausbeute können die Werte verändern.", "source": "Redaktionelle Berechnung mit allgemeinen Zutatenprofilen", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Gedämpfte Dumpling-Lasagne mit Schweinefleisch", "description": "Dumpling-Lasagne aus Wan-Tan-Blättern, Schweinehack und Weißkohl, ganz ohne Falten. Mit Schrittbildern und Tipps für saftige Schichten.", "author": "Néstor Bastidas", "image_alt": "Gedämpfte Wan-Tan-Lasagne mit Schweinehack, Kohl, Frühlingszwiebeln und Sesam", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-16x9.webp"], "faq": [{"q": "Wird sie gebacken?", "a": "Diese Variante wird in einer Form auf einem Gitter im geschlossenen Topf gedämpft. Käse und Tomatensauce kommen nicht hinein."}, {"q": "Wie bleiben die Teigblätter weich?", "a": "Blätter befeuchten, wenig überlappen und das abgemessene Wasser auf Oberfläche und Ränder verteilen. Gleichmäßig dämpfen."}, {"q": "Reicht die Fleischfarbe als Garprobe?", "a": "Nein. Mit einem Thermometer mindestens 71 °C in der mittleren Füllung prüfen."}], "additional_time_minutes": 5}, "published": false, "editorial_status": "draft"}, {"language": "fr", "slug": "lasagnes-raviolis-vapeur-porc", "public_path": "/fr/lasagnes-raviolis-vapeur-porc", "title": "Lasagnes de raviolis vapeur au porc et feuilles wonton", "excerpt": "Des couches de wonton, porc et chou cuites à la vapeur, sans plier de raviolis. Recette de dumpling lasagna avec photos et conseils pratiques.", "summary": "Les feuilles fines de wonton remplacent les pâtes italiennes dans ces lasagnes vapeur. Porc, chou, gingembre et cébettes donnent la saveur des raviolis sans les façonner un à un. Pour 4 portions, environ 70 minutes avec 5 minutes de repos.", "content_html": "<h2>À propos de cette recette</h2><p>Les feuilles fines de wonton remplacent les pâtes italiennes dans ces lasagnes vapeur. Porc, chou, gingembre et cébettes donnent la saveur des raviolis sans les façonner un à un. Pour 4 portions, environ 70 minutes avec 5 minutes de repos.</p>", "notes": "<h3>Conseils et conservation</h3><p>Utilisez des feuilles fines de wonton : les lasagnes italiennes sèches demandent une autre hydratation. Pour augmenter les portions, répartissez dans plusieurs plats avec des couches fines ; ne doublez pas automatiquement le temps et mesurez le cœur. Le poulet haché doit atteindre 74 °C. Réfrigérez rapidement les restes à 4 °C maximum, consommez sous 3 jours et réchauffez à 74 °C. Contient blé, soja et sésame ; certaines feuilles contiennent de l’œuf. La cuisson comprend environ 5 minutes pour chauffer l’eau et 35 minutes de vapeur.</p><h3>Sources</h3><ul><li><a href=\"https://lindseyeatsla.com/dumpling-lasagna/\">Lindsey Eats — dumpling lasagna technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling and temperatures</a></li></ul>", "ingredients": [{"name": "porc haché", "amount": "400", "unit": "g"}, {"name": "chou blanc, paré et séché", "amount": "150", "unit": "g"}, {"name": "cébettes", "amount": "40", "unit": "g"}, {"name": "ail pelé", "amount": "8", "unit": "g"}, {"name": "gingembre frais pelé", "amount": "10", "unit": "g"}, {"name": "sauce soja", "amount": "30", "unit": "g"}, {"name": "huile de sésame grillé", "amount": "10", "unit": "g"}, {"name": "feuilles fines de wonton", "amount": "150", "unit": "g"}, {"name": "eau pour humidifier les couches ; eau supplémentaire pour la vapeur", "amount": "90", "unit": "ml"}, {"name": "graines de sésame", "amount": "5", "unit": "g"}], "steps": [{"title": "Hachez les légumes", "content": "Lavez et séchez chou et cébettes. Hachez très finement, en réservant un peu de cébette pour servir. Râpez ail et gingembre.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-01.webp", "image_alt": "Hachez les légumes — Lasagnes de raviolis vapeur au porc et feuilles wonton"}, {"title": "Mélangez la farce", "content": "Mélangez porc froid, chou, reste des cébettes, ail, gingembre, sauce soja et huile de sésame. Répartissez bien les ingrédients sans goûter la farce crue.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-02.webp", "image_alt": "Mélangez la farce — Lasagnes de raviolis vapeur au porc et feuilles wonton"}, {"title": "Préparez la cuisson vapeur", "content": "Vérifiez qu’un plat carré de 20 cm adapté à la vapeur tient sur une grille stable dans une grande marmite couverte. L’eau reste sous le plat. Retirez-le et chauffez l’eau.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-03.webp", "image_alt": "Préparez la cuisson vapeur — Lasagnes de raviolis vapeur au porc et feuilles wonton"}, {"title": "Montez la première couche", "content": "Tapissez le fond de feuilles wonton légèrement humidifiées, en les chevauchant le moins possible. Étalez la moitié de la farce en couche fine et régulière.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-04.webp", "image_alt": "Montez la première couche — Lasagnes de raviolis vapeur au porc et feuilles wonton"}, {"title": "Terminez le montage", "content": "Ajoutez une couche de feuilles, le reste de farce et une dernière couche de feuilles : trois couches de pâte et deux de viande. Répartissez l’eau mesurée sur le dessus et les bords.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-05.webp", "image_alt": "Terminez le montage — Lasagnes de raviolis vapeur au porc et feuilles wonton"}, {"title": "Faites cuire à la vapeur", "content": "Posez prudemment le plat sur la grille et couvrez. Comptez environ 35 minutes de vapeur régulière après reprise de l’ébullition. Complétez avec de l’eau chaude si nécessaire, sans vous brûler.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-06.webp", "image_alt": "Faites cuire à la vapeur — Lasagnes de raviolis vapeur au porc et feuilles wonton"}, {"title": "Vérifiez le cœur", "content": "La farce au centre doit atteindre au moins 71 °C au thermomètre. Sinon poursuivez et vérifiez de nouveau. Sortez avec des gants et laissez reposer 5 minutes.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-07.webp", "image_alt": "Vérifiez le cœur — Lasagnes de raviolis vapeur au porc et feuilles wonton"}, {"title": "Servez avec les jus", "content": "Parsemez de cébettes réservées et de sésame. Coupez en portions et servez avec les jus ; une croûte dorée n’est pas nécessaire pour cette cuisson vapeur.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-08.webp", "image_alt": "Servez avec les jus — Lasagnes de raviolis vapeur au porc et feuilles wonton"}], "category": "Plats principaux", "course": "Plats principaux", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 25, "cook_time_minutes": 40, "total_time_minutes": 70, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "alt": "Lasagnes vapeur de wonton au porc et chou, garnies de cébettes et de sésame"}], "video_urls": [], "keywords": ["dumpling lasagna", "lasagnes wonton", "lasagnes raviolis vapeur", "raviolis sans pliage"], "nutrition": {"calories": 422.9, "protein_g": 22.2, "carbs_g": 26.8, "fat_g": 25.0, "estimated": true, "serving_size": "1 des 4 portions", "note": "Estimation par portion ; les produits et le rendement peuvent modifier ces valeurs.", "source": "Calcul éditorial à partir de profils génériques des ingrédients", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Lasagnes de raviolis vapeur au porc et feuilles wonton", "description": "Des couches de wonton, porc et chou cuites à la vapeur, sans plier de raviolis. Recette de dumpling lasagna avec photos et conseils pratiques.", "author": "Néstor Bastidas", "image_alt": "Lasagnes vapeur de wonton au porc et chou, garnies de cébettes et de sésame", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-16x9.webp"], "faq": [{"q": "Faut-il un four ?", "a": "Non, cette version cuit dans un plat sur grille, dans une marmite couverte. Elle ne contient ni fromage ni sauce tomate."}, {"q": "Comment éviter une pâte sèche ?", "a": "Humidifiez les feuilles, limitez les chevauchements et répartissez l’eau mesurée sur le dessus et les bords. Maintenez la vapeur."}, {"q": "La couleur du porc suffit-elle ?", "a": "Non. Vérifiez au thermomètre au moins 71 °C dans la farce centrale."}], "additional_time_minutes": 5}, "published": false, "editorial_status": "draft"}, {"language": "it", "slug": "lasagna-ravioli-wonton-vapore", "public_path": "/it/lasagna-ravioli-wonton-vapore", "title": "Lasagna di ravioli wonton al vapore con maiale", "excerpt": "Strati di sfoglie wonton, maiale e cavolo cotti al vapore senza chiudere ravioli. Dumpling lasagna con foto e consigli per un ripieno succoso.", "summary": "Le sfoglie sottili di wonton sostituiscono la pasta italiana in questa lasagna al vapore. Maiale, cavolo, zenzero e cipollotti danno il gusto dei ravioli senza formarli uno a uno. Per 4 porzioni, circa 70 minuti compresi 5 minuti di riposo.", "content_html": "<h2>Informazioni sulla ricetta</h2><p>Le sfoglie sottili di wonton sostituiscono la pasta italiana in questa lasagna al vapore. Maiale, cavolo, zenzero e cipollotti danno il gusto dei ravioli senza formarli uno a uno. Per 4 porzioni, circa 70 minuti compresi 5 minuti di riposo.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Usa sfoglie sottili per wonton; le lasagne italiane secche richiedono un’altra idratazione. Per più porzioni usa più pirofile mantenendo gli strati sottili: non raddoppiare automaticamente il tempo e controlla sempre il centro. Il pollo macinato deve raggiungere 74 °C. Raffredda rapidamente gli avanzi in frigorifero a non più di 4 °C, consuma entro 3 giorni e riscalda a 74 °C. Contiene frumento, soia e sesamo; alcune sfoglie contengono uovo. La cottura comprende circa 5 minuti per scaldare l’acqua e 35 di vapore.</p><h3>Fonti</h3><ul><li><a href=\"https://lindseyeatsla.com/dumpling-lasagna/\">Lindsey Eats — dumpling lasagna technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling and temperatures</a></li></ul>", "ingredients": [{"name": "carne di maiale macinata", "amount": "400", "unit": "g"}, {"name": "cavolo cappuccio bianco, pulito e asciutto", "amount": "150", "unit": "g"}, {"name": "cipollotti", "amount": "40", "unit": "g"}, {"name": "aglio sbucciato", "amount": "8", "unit": "g"}, {"name": "zenzero fresco sbucciato", "amount": "10", "unit": "g"}, {"name": "salsa di soia", "amount": "30", "unit": "g"}, {"name": "olio di sesamo tostato", "amount": "10", "unit": "g"}, {"name": "sfoglie sottili per wonton", "amount": "150", "unit": "g"}, {"name": "acqua per inumidire gli strati; altra acqua per la vaporiera", "amount": "90", "unit": "ml"}, {"name": "semi di sesamo", "amount": "5", "unit": "g"}], "steps": [{"title": "Trita le verdure", "content": "Lava e asciuga cavolo e cipollotti. Tagliali molto fini, tenendo da parte poco cipollotto per servire. Grattugia aglio e zenzero.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-01.webp", "image_alt": "Trita le verdure — Lasagna di ravioli wonton al vapore con maiale"}, {"title": "Mescola il ripieno", "content": "Unisci maiale freddo, cavolo, cipollotti rimasti, aglio, zenzero, salsa di soia e olio di sesamo. Amalgama senza assaggiare il ripieno crudo.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-02.webp", "image_alt": "Mescola il ripieno — Lasagna di ravioli wonton al vapore con maiale"}, {"title": "Prepara la vaporiera", "content": "Controlla che una pirofila quadrata di 20 cm adatta al vapore entri su una griglia stabile in una pentola larga con coperchio. L’acqua non deve toccarla. Togli la pirofila e scalda l’acqua.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-03.webp", "image_alt": "Prepara la vaporiera — Lasagna di ravioli wonton al vapore con maiale"}, {"title": "Forma il primo strato", "content": "Copri il fondo con sfoglie wonton leggermente inumidite, sovrapponendole il meno possibile. Stendi metà ripieno in uno strato sottile e uniforme.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-04.webp", "image_alt": "Forma il primo strato — Lasagna di ravioli wonton al vapore con maiale"}, {"title": "Completa gli strati", "content": "Aggiungi altre sfoglie, il ripieno rimasto e un ultimo strato di sfoglie: tre di pasta e due di carne. Distribuisci l’acqua misurata sulla superficie e sui bordi.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-05.webp", "image_alt": "Completa gli strati — Lasagna di ravioli wonton al vapore con maiale"}, {"title": "Cuoci al vapore", "content": "Appoggia con cautela la pirofila sulla griglia e copri. Cuoci con vapore costante per circa 35 minuti dalla ripresa del bollore. Rabbocca con acqua calda se serve, proteggendoti dal vapore.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-06.webp", "image_alt": "Cuoci al vapore — Lasagna di ravioli wonton al vapore con maiale"}, {"title": "Controlla il centro", "content": "Il ripieno centrale deve raggiungere almeno 71 °C al termometro. Se necessario continua e ricontrolla. Estrai con guanti da forno e lascia riposare 5 minuti.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-07.webp", "image_alt": "Controlla il centro — Lasagna di ravioli wonton al vapore con maiale"}, {"title": "Servi gli strati succosi", "content": "Completa con cipollotto tenuto da parte e sesamo. Taglia a porzioni e servi con i succhi; questa preparazione al vapore non richiede una crosta dorata.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-08.webp", "image_alt": "Servi gli strati succosi — Lasagna di ravioli wonton al vapore con maiale"}], "category": "Secondi piatti", "course": "Secondi piatti", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 25, "cook_time_minutes": 40, "total_time_minutes": 70, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "alt": "Lasagna di wonton al vapore con strati di maiale e cavolo, cipollotto e sesamo"}], "video_urls": [], "keywords": ["dumpling lasagna", "lasagna wonton", "ravioli al vapore senza pieghe", "lasagna di ravioli"], "nutrition": {"calories": 422.9, "protein_g": 22.2, "carbs_g": 26.8, "fat_g": 25.0, "estimated": true, "serving_size": "1 di 4 porzioni", "note": "Stima per porzione; prodotti e resa possono modificare questi valori.", "source": "Calcolo redazionale con profili generici degli ingredienti", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Lasagna di ravioli wonton al vapore con maiale", "description": "Strati di sfoglie wonton, maiale e cavolo cotti al vapore senza chiudere ravioli. Dumpling lasagna con foto e consigli per un ripieno succoso.", "author": "Néstor Bastidas", "image_alt": "Lasagna di wonton al vapore con strati di maiale e cavolo, cipollotto e sesamo", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-16x9.webp"], "faq": [{"q": "Si cuoce in forno?", "a": "Questa versione cuoce al vapore in una pirofila su griglia dentro una pentola coperta. Non contiene formaggio né pomodoro."}, {"q": "Come evitare sfoglie asciutte?", "a": "Inumidiscile, sovrapponile poco e distribuisci l’acqua misurata su superficie e bordi. Mantieni il vapore costante."}, {"q": "Basta il colore del maiale?", "a": "No. Controlla con un termometro almeno 71 °C nel ripieno centrale."}], "additional_time_minutes": 5}, "published": false, "editorial_status": "draft"}, {"language": "ja", "slug": "steamed-wonton-dumpling-lasagna", "public_path": "/ja/steamed-wonton-dumpling-lasagna", "title": "包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ", "excerpt": "ワンタンの皮と豚ひき肉、キャベツを重ねて蒸すダンプリングラザニア。包む手間を省き、写真付きの手順でしっとり仕上げます。", "summary": "イタリアのパスタの代わりに薄いワンタンの皮を使い、蒸して作るラザニアです。豚肉、キャベツ、しょうが、青ねぎを重ね、ひとつずつ包まずにワンタン風の味を楽しみます。4人分、蒸らし5分を含めて約70分です。", "content_html": "<h2>このレシピについて</h2><p>イタリアのパスタの代わりに薄いワンタンの皮を使い、蒸して作るラザニアです。豚肉、キャベツ、しょうが、青ねぎを重ね、ひとつずつ包まずにワンタン風の味を楽しみます。4人分、蒸らし5分を含めて約70分です。</p>", "notes": "<h3>コツと保存方法</h3><p>薄いワンタンの皮を使ってください。乾燥したイタリアのラザニア用パスタは必要な水分が違うため、そのまま代用できません。人数を増やす場合は容器を増やし、層を薄く保ちます。加熱時間を単純に倍にせず、中心温度を確認します。鶏ひき肉に替える場合は中心74 °C以上にします。残りは速やかに4 °C以下で冷蔵し、3日以内に食べ、再加熱は74 °Cまで行います。小麦、大豆、ごまを含み、皮によっては卵も含みます。加熱時間には湯を沸かす約5分と蒸す35分を含みます。</p><h3>参考資料</h3><ul><li><a href=\"https://lindseyeatsla.com/dumpling-lasagna/\">Lindsey Eats — dumpling lasagna technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling and temperatures</a></li></ul>", "ingredients": [{"name": "豚ひき肉", "amount": "400", "unit": "g"}, {"name": "キャベツ（下処理して水気を拭いたもの）", "amount": "150", "unit": "g"}, {"name": "青ねぎ", "amount": "40", "unit": "g"}, {"name": "皮をむいたにんにく", "amount": "8", "unit": "g"}, {"name": "皮をむいたしょうが", "amount": "10", "unit": "g"}, {"name": "しょうゆ", "amount": "30", "unit": "g"}, {"name": "焙煎ごま油", "amount": "10", "unit": "g"}, {"name": "薄いワンタンの皮", "amount": "150", "unit": "g"}, {"name": "皮を湿らせる水（蒸し器用は別に用意）", "amount": "90", "unit": "ml"}, {"name": "ごま", "amount": "5", "unit": "g"}], "steps": [{"title": "野菜を細かく切る", "content": "キャベツと青ねぎを洗って水気を拭き、ごく細かく切ります。仕上げ用の青ねぎを少し取り分け、にんにくとしょうがをすりおろします。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-01.webp", "image_alt": "野菜を細かく切る — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}, {"title": "肉だねを混ぜる", "content": "冷たい豚ひき肉にキャベツ、残りの青ねぎ、にんにく、しょうが、しょうゆ、ごま油を加えて均一に混ぜます。生の肉だねは味見しません。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-02.webp", "image_alt": "肉だねを混ぜる — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}, {"title": "蒸し器を準備する", "content": "蒸し調理に使える20 cm角の耐熱容器が、ふた付きの大きな鍋の安定した網に載るか確認します。水は容器に触れない高さにし、容器を外して沸かします。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-03.webp", "image_alt": "蒸し器を準備する — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}, {"title": "最初の層を作る", "content": "軽く湿らせたワンタンの皮を、重なりを少なくして容器の底に敷きます。肉だねの半量を薄く均一に広げます。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-04.webp", "image_alt": "最初の層を作る — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}, {"title": "重ねて水を加える", "content": "皮、残りの肉だね、最後の皮を重ねます。皮3層、肉2層にし、分量の水を表面と縁に分けて注ぎます。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-05.webp", "image_alt": "重ねて水を加える — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}, {"title": "蒸して火を通す", "content": "容器を網に慎重に載せてふたをします。再沸騰してから約35分、一定の蒸気で蒸します。必要なら熱湯を足し、蒸気によるやけどに注意します。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-06.webp", "image_alt": "蒸して火を通す — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}, {"title": "中心温度を確認する", "content": "中心の肉だねが71 °C以上になったことを温度計で確認します。足りなければ加熱を続けて再確認し、ミトンで取り出して5分休ませます。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-07.webp", "image_alt": "中心温度を確認する — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}, {"title": "しっとり盛り付ける", "content": "取り分けた青ねぎとごまを散らします。切り分けて煮汁と一緒に盛ります。蒸し料理なので、表面に焼き色を付ける必要はありません。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-08.webp", "image_alt": "しっとり盛り付ける — 包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ"}], "category": "主菜", "course": "主菜", "cuisine": "インターナショナル", "difficulty": "簡単", "prep_time_minutes": 25, "cook_time_minutes": 40, "total_time_minutes": 70, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "alt": "ワンタンの皮、豚肉、キャベツを重ねた蒸しラザニアと青ねぎ、ごま"}], "video_urls": [], "keywords": ["包まないワンタン", "ダンプリングラザニア", "ワンタン 蒸し料理", "dumpling lasagna"], "nutrition": {"calories": 422.9, "protein_g": 22.2, "carbs_g": 26.8, "fat_g": 25.0, "estimated": true, "serving_size": "4人分のうち1人分", "note": "1人分の推定値です。使用する製品や出来上がり量によって変わります。", "source": "材料の一般的な栄養成分から算出した編集部による推定", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "包まないワンタンの蒸しラザニア｜豚ひき肉とキャベツ", "description": "ワンタンの皮と豚ひき肉、キャベツを重ねて蒸すダンプリングラザニア。包む手間を省き、写真付きの手順でしっとり仕上げます。", "author": "Néstor Bastidas", "image_alt": "ワンタンの皮、豚肉、キャベツを重ねた蒸しラザニアと青ねぎ、ごま", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-16x9.webp"], "faq": [{"q": "オーブンで焼きますか？", "a": "このレシピは、ふた付きの鍋に網と耐熱容器を入れて蒸します。チーズやトマトソースは使いません。"}, {"q": "皮の乾燥を防ぐには？", "a": "皮を湿らせ、重なりを少なくします。分量の水を表面と縁に分け、蒸気が途切れないようにします。"}, {"q": "豚肉の色だけで判断できますか？", "a": "いいえ。温度計で中心の肉だねが71 °C以上になったことを確認してください。"}], "additional_time_minutes": 5}, "published": false, "editorial_status": "draft"}, {"language": "pt", "slug": "lasanha-dumplings-vapor-porco", "public_path": "/pt/lasanha-dumplings-vapor-porco", "title": "Lasanha de dumplings no vapor com porco e wonton", "excerpt": "Camadas de massa wonton, carne suína e repolho cozidas no vapor, sem dobrar bolinhos. Receita com fotos e dicas para um recheio suculento.", "summary": "A massa fina de wonton substitui a lasanha italiana nesta receita feita no vapor. Carne suína, repolho, gengibre e cebolinha dão sabor de dumpling sem modelar cada bolinho. Rende 4 porções e leva cerca de 70 minutos, incluindo 5 minutos de descanso.", "content_html": "<h2>Sobre esta receita</h2><p>A massa fina de wonton substitui a lasanha italiana nesta receita feita no vapor. Carne suína, repolho, gengibre e cebolinha dão sabor de dumpling sem modelar cada bolinho. Rende 4 porções e leva cerca de 70 minutos, incluindo 5 minutos de descanso.</p>", "notes": "<h3>Dicas e conservação</h3><p>Use massa fina de wonton; a massa seca de lasanha italiana exige outra hidratação. Para aumentar porções, divida em mais refratários mantendo camadas finas; não dobre o tempo automaticamente e confira sempre o centro. Frango moído precisa atingir 74 °C. Refrigere as sobras rapidamente a 4 °C ou menos, consuma em 3 dias e reaqueça até 74 °C. Contém trigo, soja e gergelim; algumas massas têm ovo. O tempo de cozimento inclui aproximadamente 5 minutos para aquecer a água e 35 de vapor.</p><h3>Fontes</h3><ul><li><a href=\"https://lindseyeatsla.com/dumpling-lasagna/\">Lindsey Eats — dumpling lasagna technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling and temperatures</a></li></ul>", "ingredients": [{"name": "carne suína moída", "amount": "400", "unit": "g"}, {"name": "repolho branco, limpo e seco", "amount": "150", "unit": "g"}, {"name": "cebolinha", "amount": "40", "unit": "g"}, {"name": "alho descascado", "amount": "8", "unit": "g"}, {"name": "gengibre fresco descascado", "amount": "10", "unit": "g"}, {"name": "molho de soja", "amount": "30", "unit": "g"}, {"name": "óleo de gergelim torrado", "amount": "10", "unit": "g"}, {"name": "massas finas de wonton", "amount": "150", "unit": "g"}, {"name": "água para umedecer as camadas; mais água para a panela de vapor", "amount": "90", "unit": "ml"}, {"name": "sementes de gergelim", "amount": "5", "unit": "g"}], "steps": [{"title": "Pique os vegetais", "content": "Lave e seque repolho e cebolinha. Pique bem fino, reservando um pouco de cebolinha para servir. Rale alho e gengibre.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-01.webp", "image_alt": "Pique os vegetais — Lasanha de dumplings no vapor com porco e wonton"}, {"title": "Misture o recheio", "content": "Junte carne suína fria, repolho, cebolinha restante, alho, gengibre, molho de soja e óleo de gergelim. Misture até distribuir tudo, sem provar o recheio cru.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-02.webp", "image_alt": "Misture o recheio — Lasanha de dumplings no vapor com porco e wonton"}, {"title": "Prepare a panela de vapor", "content": "Confira se um refratário quadrado de 20 cm próprio para vapor cabe numa panela larga com tampa sobre uma grade estável. A água fica abaixo do refratário. Retire-o e aqueça a água.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-03.webp", "image_alt": "Prepare a panela de vapor — Lasanha de dumplings no vapor com porco e wonton"}, {"title": "Monte a primeira camada", "content": "Forre o fundo com massas wonton levemente umedecidas, sobrepondo o mínimo possível. Espalhe metade do recheio numa camada fina e uniforme.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-04.webp", "image_alt": "Monte a primeira camada — Lasanha de dumplings no vapor com porco e wonton"}, {"title": "Complete as camadas", "content": "Acrescente outra camada de massa, o recheio restante e a última camada de massa: três de massa e duas de carne. Distribua a água medida sobre a superfície e as bordas.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-05.webp", "image_alt": "Complete as camadas — Lasanha de dumplings no vapor com porco e wonton"}, {"title": "Cozinhe no vapor", "content": "Coloque o refratário com cuidado sobre a grade e tampe. Cozinhe com vapor constante por cerca de 35 minutos depois de voltar a ferver. Reponha água quente se necessário, protegendo-se do vapor.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-06.webp", "image_alt": "Cozinhe no vapor — Lasanha de dumplings no vapor com porco e wonton"}, {"title": "Confira o centro", "content": "O recheio central deve atingir pelo menos 71 °C no termômetro. Se não atingir, continue e confira novamente. Retire com luvas e deixe descansar por 5 minutos.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-07.webp", "image_alt": "Confira o centro — Lasanha de dumplings no vapor com porco e wonton"}, {"title": "Sirva as camadas suculentas", "content": "Espalhe a cebolinha reservada e o gergelim. Corte em porções e sirva com os sucos; esta preparação no vapor não precisa de crosta dourada.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/paso-08.webp", "image_alt": "Sirva as camadas suculentas — Lasanha de dumplings no vapor com porco e wonton"}], "category": "Pratos principais", "course": "Pratos principais", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 25, "cook_time_minutes": 40, "total_time_minutes": 70, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada.webp", "alt": "Lasanha de wonton no vapor com camadas de carne suína, repolho, cebolinha e gergelim"}], "video_urls": [], "keywords": ["lasanha de dumplings", "dumpling lasagna", "lasanha wonton", "dumplings sem dobrar"], "nutrition": {"calories": 422.9, "protein_g": 22.2, "carbs_g": 26.8, "fat_g": 25.0, "estimated": true, "serving_size": "1 de 4 porções", "note": "Estimativa por porção; os produtos e o rendimento podem alterar os valores.", "source": "Cálculo editorial com perfis genéricos dos ingredientes", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Lasanha de dumplings no vapor com porco e wonton", "description": "Camadas de massa wonton, carne suína e repolho cozidas no vapor, sem dobrar bolinhos. Receita com fotos e dicas para um recheio suculento.", "author": "Néstor Bastidas", "image_alt": "Lasanha de wonton no vapor com camadas de carne suína, repolho, cebolinha e gergelim", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/lasana-dumplings-al-vapor/portada-16x9.webp"], "faq": [{"q": "Vai ao forno?", "a": "Esta versão cozinha no vapor num refratário sobre grade dentro de uma panela tampada. Não leva queijo nem molho de tomate."}, {"q": "Como evitar massa seca?", "a": "Umedeça as folhas, sobreponha pouco e distribua a água medida sobre a superfície e as bordas. Mantenha o vapor constante."}, {"q": "A cor indica que o porco está pronto?", "a": "Não é uma verificação confiável. Use um termômetro e confira pelo menos 71 °C no recheio central."}], "additional_time_minutes": 5}, "published": false, "editorial_status": "draft"}]$payload$::jsonb;
foods jsonb := $foods$[{"slug": "aceite-sesamo-tostado", "name": "Aceite de sésamo tostado", "description": "Aceite aromático de semillas de sésamo tostadas."}, {"slug": "obleas-wonton", "name": "Obleas de wonton", "description": "Láminas finas de masa para wonton; revisar si contienen huevo."}]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "carne-de-cerdo-molida", "alias": "carne de cerdo molida"}, {"slug": "repollo", "alias": "repollo blanco, limpio y seco"}, {"slug": "cebolleta", "alias": "cebolleta"}, {"slug": "ajo", "alias": "ajo pelado"}, {"slug": "jengibre", "alias": "jengibre fresco pelado"}, {"slug": "salsa-de-soja", "alias": "salsa de soja"}, {"slug": "aceite-sesamo-tostado", "alias": "aceite de sésamo tostado"}, {"slug": "obleas-wonton", "alias": "obleas de wonton finas"}, {"slug": "agua", "alias": "agua para humedecer las capas; aparte, agua para la vaporera"}, {"slug": "semillas-de-sesamo", "alias": "semillas de sésamo"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe URL already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredients WHERE lower(name)=lower(a->>'name') AND slug<>a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Canonical name collision'; END IF;
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),a->>'description','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing canonical ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>10 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
END $stage$;
SELECT id,recipe_group_id,language,slug,published,editorial_status FROM public.recipes WHERE public_path IN ('/lasana-dumplings-al-vapor','/en/steamed-dumpling-lasagna','/de/dumpling-lasagne-gedaempft','/fr/lasagnes-raviolis-vapeur-porc','/it/lasagna-ravioli-wonton-vapore','/ja/steamed-wonton-dumpling-lasagna','/pt/lasanha-dumplings-vapor-porco') ORDER BY language;
